fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // The sum of absolute deviations is minimized at the median.
    // For three distinct values, the total distance equals max - min.
    let min_val = x1.min(x2).min(x3);
    let max_val = x1.max(x2).max(x3);
    max_val - min_val
}

